CREATE TABLE "User" ("id" UUID NOT NULL, "email" VARCHAR(254) NOT NULL, "displayName" VARCHAR(100) NOT NULL, "passwordHash" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
